  text-align: right;
  white-space: pre-wrap;
}
</style>
<small>shape: (4, 6)</small><table border="1" class="dataframe"><thead><tr><th>Item</th><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th></tr><tr><td>str</td><td>i64</td><td>i64</td><td>i64</td><td>i64</td><td>i64</td></tr></thead><tbody><tr><td>&quot;Photoshop&quot;</td><td>25</td><td>30</td><td>28</td><td>26</td><td>27</td></tr><tr><td>&quot;CorelDRAW&quot;</td><td>18</td><td>20</td><td>22</td><td>21</td><td>19</td></tr><tr><td>&quot;Netscape&quot;</td><td>22</td><td>24</td><td>19</td><td>23</td><td>25</td></tr><tr><td>&quot;Encarta&quot;</td><td>15</td><td>17</td><td>20</td><td>18</td><td>16</td></tr></tbody></table></div>
```
:::
